values
('bmlt-urinalysis-routine-path-mcq-001','BMLT','BMLT NHPC Licensing','mcq','free',2400,$json${"question":"Normal urine is usually:","translation":"","options":["Clear and pale yellow","Opaque red","Milky blue","Black"],"correctIndex":0,"explanation":"Normal urine is usually clear and ranges from pale to deep yellow.","explanationNe":"सामान्य पिसाब सफा र हल्का देखि गाढा पहेँलो हुन्छ।","topic":"Urinalysis and Routine Clinical Pathology"}$json$::jsonb,true),
('bmlt-urinalysis-routine-path-mcq-002','BMLT','BMLT NHPC Licensing','mcq','free',2401,$json${"question":"The yellow colour of urine is mainly due to:","translation":"","options":["Urochrome","Hemoglobin","Bilirubin only","Melanin"],"correctIndex":0,"explanation":"Urochrome is the principal pigment responsible for normal urine colour.","explanationNe":"Urochrome सामान्य पिसाबको पहेँलो रङको मुख्य pigment हो।","topic":"Urinalysis and Routine Clinical Pathology"}$json$::jsonb,true),
('bmlt-urinalysis-routine-path-mcq-003','BMLT','BMLT NHPC Licensing','mcq','free',2402,$json${"question":"The usual urine pH range is approximately:","translation":"","options":["4.5–8.0","1.0–2.0","9.5–12.0","12.0–14.0"],"correctIndex":0,"explanation":"Urine pH commonly ranges from about 4.5 to 8, with variation from diet and physiology.","explanationNe":"पिसाबको pH सामान्यतया करिब ४.५–८.० हुन्छ।","topic":"Urinalysis and Routine Clinical Pathology"}$json$::jsonb,true),
('bmlt-urinalysis-routine-path-mcq-004','BMLT','BMLT NHPC Licensing','mcq','free',2403,$json${"question":"A urine reagent strip should be read:","translation":"","options":["At the manufacturer-specified time","Immediately for every pad","After one hour","Only after drying"],"correctIndex":0,"explanation":"Each reagent pad has a specified read time; follow the strip instructions.","explanationNe":"प्रत्येक pad तोकिएको समयमा पढ्नुपर्छ।","topic":"Urinalysis and Routine Clinical Pathology"}$json$::jsonb,true),
('bmlt-urinalysis-routine-path-mcq-005','BMLT','BMLT NHPC Licensing','mcq','free',2404,$json${"question":"The urine protein dipstick is most sensitive to:","translation":"","options":["Albumin","Bence Jones protein only","Hemoglobin only","Myoglobin only"],"correctIndex":0,"explanation":"The dipstick protein pad primarily detects albumin and may miss other proteins.","explanationNe":"Dipstick protein test मुख्यतः albumin पत्ता लगाउन संवेदनशील हुन्छ।","topic":"Urinalysis and Routine Clinical Pathology"}$json$::jsonb,true),
('bmlt-urinalysis-routine-path-mcq-006','BMLT','BMLT NHPC Licensing','mcq','free',2405,$json${"question":"Microalbuminuria is best assessed using:","translation":"","options":["Urine albumin-to-creatinine ratio","Urine glucose strip","Urine ketone strip","Urine colour chart"],"correctIndex":0,"explanation":"Urine albumin-to-creatinine ratio is commonly used to assess moderately increased albumin excretion.","explanationNe":"Albumin-to-creatinine ratio ले पिसाबमा albumin बढेको मूल्याङ्कन गर्छ।","topic":"Urinalysis and Routine Clinical Pathology"}$json$::jsonb,true),
('bmlt-urinalysis-routine-path-mcq-007','BMLT','BMLT NHPC Licensing','mcq','free',2406,$json${"question":"A positive urine glucose test may occur in:","translation":"","options":["Hyperglycemia exceeding renal threshold","Iron deficiency","Low serum sodium","Hypocalcemia only"],"correctIndex":0,"explanation":"Glucosuria commonly occurs when blood glucose exceeds renal reabsorptive capacity, though renal causes also exist.","explanationNe":"रगतको glucose renal threshold भन्दा माथि हुँदा पिसाबमा glucose आउन सक्छ।","topic":"Urinalysis and Routine Clinical Pathology"}$json$::jsonb,true),
('bmlt-urinalysis-routine-path-mcq-008','BMLT','BMLT NHPC Licensing','mcq','free',2407,$json${"question":"Urine ketone testing detects mainly:","translation":"","options":["Acetoacetate","Lactate","Urea","Creatinine"],"correctIndex":0,"explanation":"Nitroprusside-based strips detect acetoacetate, not beta-hydroxybutyrate well.","explanationNe":"Ketone strip ले मुख्यतः acetoacetate पत्ता लगाउँछ।","topic":"Urinalysis and Routine Clinical Pathology"}$json$::jsonb,true),
('bmlt-urinalysis-routine-path-mcq-009','BMLT','BMLT NHPC Licensing','mcq','free',2408,$json${"question":"The urine blood pad may detect:","translation":"","options":["RBCs, free hemoglobin or myoglobin","Only intact RBCs","Only bilirubin","Only albumin"],"correctIndex":0,"explanation":"The blood pad detects heme activity and can be positive with RBCs, hemoglobin or myoglobin.","explanationNe":"Blood pad heme पत्ता लगाउने भएकाले RBC, hemoglobin वा myoglobin हुँदा positive हुन सक्छ।","topic":"Urinalysis and Routine Clinical Pathology"}$json$::jsonb,true),
('bmlt-urinalysis-routine-path-mcq-010','BMLT','BMLT NHPC Licensing','mcq','free',2409,$json${"question":"Urine urobilinogen may be increased in:","translation":"","options":["Hemolytic disorders","Complete biliary obstruction only","Diabetes insipidus","Iron deficiency"],"correctIndex":0,"explanation":"Increased bilirubin production in hemolysis can increase urinary urobilinogen.","explanationNe":"Hemolysis मा bilirubin उत्पादन बढ्दा urine urobilinogen बढ्न सक्छ।","topic":"Urinalysis and Routine Clinical Pathology"}$json$::jsonb,true),
('bmlt-urinalysis-routine-path-mcq-011','BMLT','BMLT NHPC Licensing','mcq','free',2410,$json${"question":"A urine sample for routine microscopy is ideally examined:","translation":"","options":["Fresh, preferably within two hours","After 24 hours at room temperature","After adding formalin in every case","After boiling"],"correctIndex":0,"explanation":"Prompt examination limits deterioration of cells, casts and other formed elements.","explanationNe":"ताजा पिसाब छिटो जाँच्दा cell र cast बिग्रन पाउँदैनन्।","topic":"Urinalysis and Routine Clinical Pathology"}$json$::jsonb,true),
('bmlt-urinalysis-routine-path-mcq-012','BMLT','BMLT NHPC Licensing','mcq','free',2411,$json${"question":"Squamous epithelial cells in urine commonly indicate:","translation":"","options":["Possible contamination from external genital surfaces","Glomerular injury in every case","Renal tubular necrosis","Bacterial sepsis"],"correctIndex":0,"explanation":"Numerous squamous epithelial cells often suggest contamination during collection.","explanationNe":"धेरै squamous epithelial cell देखिनु नमुना contamination को संकेत हुन सक्छ।","topic":"Urinalysis and Routine Clinical Pathology"}$json$::jsonb,true),
('bmlt-urinalysis-routine-path-mcq-013','BMLT','BMLT NHPC Licensing','mcq','free',2412,$json${"question":"Renal tubular epithelial cells in urine may suggest:","translation":"","options":["Tubular injury","Normal finding in large numbers","Bladder contamination only","Liver failure"],"correctIndex":0,"explanation":"Increased renal tubular epithelial cells can occur with tubular damage.","explanationNe":"Renal tubular epithelial cell बढ्नु tubular injury सँग सम्बन्धित हुन सक्छ।","topic":"Urinalysis and Routine Clinical Pathology"}$json$::jsonb,true),
('bmlt-urinalysis-routine-path-mcq-014','BMLT','BMLT NHPC Licensing','mcq','free',2413,$json${"question":"Waxy casts are often associated with:","translation":"","options":["Advanced chronic renal disease","Normal exercise","Acute cystitis only","Healthy newborn urine"],"correctIndex":0,"explanation":"Waxy casts may be seen in advanced renal disease and low-flow states.","explanationNe":"Waxy cast उन्नत मिर्गौला रोगमा देखिन सक्छ।","topic":"Urinalysis and Routine Clinical Pathology"}$json$::jsonb,true),
('bmlt-urinalysis-routine-path-mcq-015','BMLT','BMLT NHPC Licensing','mcq','free',2414,$json${"question":"Broad casts are classically associated with:","translation":"","options":["Advanced renal failure","Normal urine","Uncomplicated cystitis","Dehydration alone"],"correctIndex":0,"explanation":"Broad casts form in dilated tubules and are associated with advanced renal disease.","explanationNe":"Broad cast फैलिएका tubule मा बन्ने र उन्नत renal disease सँग सम्बन्धित हुन्छ।","topic":"Urinalysis and Routine Clinical Pathology"}$json$::jsonb,true),
('bmlt-urinalysis-routine-path-mcq-016','BMLT','BMLT NHPC Licensing','mcq','free',2415,$json${"question":"Calcium oxalate crystals may appear as:","translation":"","options":["Envelope-shaped crystals","Needle-shaped only","Hexagonal plates only","Coffin-lid prisms"],"correctIndex":0,"explanation":"Calcium oxalate dihydrate crystals often have an envelope appearance.","explanationNe":"Calcium oxalate crystal प्रायः envelope आकारको देखिन्छ।","topic":"Urinalysis and Routine Clinical Pathology"}$json$::jsonb,true),
('bmlt-urinalysis-routine-path-mcq-017','BMLT','BMLT NHPC Licensing','mcq','free',2416,$json${"question":"Triple phosphate crystals are typically:","translation":"","options":["Coffin-lid shaped","Envelope shaped","Hexagonal","Needle-shaped"],"correctIndex":0,"explanation":"Struvite or triple phosphate crystals commonly have a coffin-lid appearance.","explanationNe":"Triple phosphate crystal प्रायः coffin-lid आकारको हुन्छ।","topic":"Urinalysis and Routine Clinical Pathology"}$json$::jsonb,true),
('bmlt-urinalysis-routine-path-mcq-018','BMLT','BMLT NHPC Licensing','mcq','free',2417,$json${"question":"Cystine crystals are characteristically:","translation":"","options":["Hexagonal","Coffin-lid","Envelope","Rhomboid only"],"correctIndex":0,"explanation":"Cystine crystals are classically hexagonal and may indicate cystinuria.","explanationNe":"Cystine crystal hexagonal हुन्छ र cystinuria को संकेत हुन सक्छ।","topic":"Urinalysis and Routine Clinical Pathology"}$json$::jsonb,true),
('bmlt-urinalysis-routine-path-mcq-019','BMLT','BMLT NHPC Licensing','mcq','free',2418,$json${"question":"Uric acid crystals commonly form in:","translation":"","options":["Acidic urine","Strongly alkaline urine only","Neutral distilled water","Serum"],"correctIndex":0,"explanation":"Uric acid precipitates more readily in acidic urine.","explanationNe":"Uric acid crystal अम्लीय पिसाबमा सजिलै बन्न सक्छ।","topic":"Urinalysis and Routine Clinical Pathology"}$json$::jsonb,true),
('bmlt-urinalysis-routine-path-mcq-020','BMLT','BMLT NHPC Licensing','mcq','free',2419,$json${"question":"The presence of oval fat bodies in urine is associated with:","translation":"","options":["Lipiduria, often in nephrotic syndrome","Acute appendicitis","Iron deficiency","Viral hepatitis"],"correctIndex":0,"explanation":"Oval fat bodies represent lipid-containing cells and are associated with nephrotic syndrome.","explanationNe":"Oval fat body lipiduria मा देखिन्छ र nephrotic syndrome सँग सम्बन्धित हुन्छ।","topic":"Urinalysis and Routine Clinical Pathology"}$json$::jsonb,true),
('bmlt-urinalysis-routine-path-mcq-021','BMLT','BMLT NHPC Licensing','mcq','free',2420,$json${"question":"A urine sample for culture is preferably collected by:","translation":"","options":["Clean-catch midstream method","Collecting the first drops only","Using a non-sterile open cup","Pooling urine from several voids"],"correctIndex":0,"explanation":"Clean-catch midstream collection reduces contamination for culture.","explanationNe":"Culture का लागि clean-catch midstream urine उपयुक्त हुन्छ।","topic":"Urinalysis and Routine Clinical Pathology"}$json$::jsonb,true),
('bmlt-urinalysis-routine-path-mcq-022','BMLT','BMLT NHPC Licensing','mcq','free',2421,$json${"question":"A catheter urine culture specimen should be collected from:","translation":"","options":["Disinfected sampling port using aseptic technique","The drainage bag","The catheter exterior","A bedpan"],"correctIndex":0,"explanation":"Urine for culture from an indwelling catheter should be taken aseptically from the sampling port, not the bag.","explanationNe":"Catheter urine culture sampling port बाट aseptic तरिकाले लिनुपर्छ, bag बाट होइन।","topic":"Urinalysis and Routine Clinical Pathology"}$json$::jsonb,true),
('bmlt-urinalysis-routine-path-mcq-023','BMLT','BMLT NHPC Licensing','mcq','free',2422,$json${"question":"A urine culture colony count should be interpreted with:","translation":"","options":["Symptoms, collection method and organism identity","Colour alone","Patient height only","Urine pH alone"],"correctIndex":0,"explanation":"Significance depends on symptoms, specimen quality, organism and quantitative growth.","explanationNe":"Colony count लाई लक्षण, नमुना विधि र जीवाणुको प्रकारसँग मिलाएर बुझिन्छ।","topic":"Urinalysis and Routine Clinical Pathology"}$json$::jsonb,true),
('bmlt-urinalysis-routine-path-mcq-024','BMLT','BMLT NHPC Licensing','mcq','free',2423,$json${"question":"Nitrite-negative urine dipstick:","translation":"","options":["Does not exclude urinary tract infection","Always excludes UTI","Confirms fungal infection","Confirms renal failure"],"correctIndex":0,"explanation":"Some organisms do not reduce nitrate, and frequent voiding may yield a false-negative nitrite result.","explanationNe":"Nitrite negative हुँदैमा UTI नकारिँदैन।","topic":"Urinalysis and Routine Clinical Pathology"}$json$::jsonb,true),
('bmlt-urinalysis-routine-path-mcq-025','BMLT','BMLT NHPC Licensing','mcq','free',2424,$json${"question":"A urine sample with abundant bacteria but few WBCs may reflect:","translation":"","options":["Contamination or asymptomatic bacteriuria, depending on context","Definite pyelonephritis","Always glomerulonephritis","Always tuberculosis"],"correctIndex":0,"explanation":"Bacteriuria without pyuria requires clinical and collection-context interpretation.","explanationNe":"Bacteria धेरै तर WBC कम भए contamination वा asymptomatic bacteriuria हुन सक्छ।","topic":"Urinalysis and Routine Clinical Pathology"}$json$::jsonb,true),
('bmlt-urinalysis-routine-path-mock-001','BMLT','BMLT NHPC Licensing','mock','free',2400,$json${"question":"The most appropriate preservative for routine urine culture is generally:","translation":"","options":["No chemical preservative; refrigerate if delay is expected","Formalin","Strong acid","Bleach"],"correctIndex":0,"explanation":"Culture specimens are usually processed promptly or refrigerated if transport is delayed; chemical preservatives can interfere.","explanationNe":"Urine culture नमुना छिटो पठाउने वा ढिलाइ भए चिसोमा राख्ने गरिन्छ।","topic":"Urinalysis and Routine Clinical Pathology"}$json$::jsonb,true),
('bmlt-urinalysis-routine-path-mock-002','BMLT','BMLT NHPC Licensing','mock','free',2401,$json${"question":"A 24-hour urine collection should be rejected or recollected if:","translation":"","options":["A significant portion is missed","The volume is large","The container is labelled","The patient records start time"],"correctIndex":0,"explanation":"Missing any void compromises total timed excretion and may invalidate the collection.","explanationNe":"२४ घण्टाको पिसाबमध्ये कुनै भाग छुटे परिणाम अमान्य हुन सक्छ।","topic":"Urinalysis and Routine Clinical Pathology"}$json$::jsonb,true),
('bmlt-urinalysis-routine-path-mock-003','BMLT','BMLT NHPC Licensing','mock','free',2402,$json${"question":"Urine osmolality reflects:","translation":"","options":["Number of dissolved particles per kilogram of water","Urine colour","RBC size","Bacterial shape"],"correctIndex":0,"explanation":"Osmolality measures the concentration of osmotically active particles.","explanationNe":"Osmolality ले पानीको प्रति किलोग्राम घुलित कणको संख्या जनाउँछ।","topic":"Urinalysis and Routine Clinical Pathology"}$json$::jsonb,true),
('bmlt-urinalysis-routine-path-mock-004','BMLT','BMLT NHPC Licensing','mock','free',2403,$json${"question":"A low urine specific gravity close to 1.000 may be seen in:","translation":"","options":["Very dilute urine","Severe dehydration","Heavy glycosuria","Marked proteinuria"],"correctIndex":0,"explanation":"Very dilute urine has a specific gravity near that of water.","explanationNe":"धेरै dilute पिसाबको specific gravity पानीको नजिक हुन्छ।","topic":"Urinalysis and Routine Clinical Pathology"}$json$::jsonb,true),
('bmlt-urinalysis-routine-path-mock-005','BMLT','BMLT NHPC Licensing','mock','free',2404,$json${"question":"A high urine specific gravity may result from:","translation":"","options":["Glucose or protein in urine","Pure water diuresis","Low solute intake only","Repeated dilution"],"correctIndex":0,"explanation":"Large solute molecules such as glucose and protein can increase specific gravity.","explanationNe":"Glucose वा protein जस्ता पदार्थले specific gravity बढाउन सक्छन्।","topic":"Urinalysis and Routine Clinical Pathology"}$json$::jsonb,true),
('bmlt-urinalysis-routine-path-mock-006','BMLT','BMLT NHPC Licensing','mock','free',2405,$json${"question":"The term oliguria in adults commonly refers to urine output below approximately:","translation":"","options":["400 mL per day","2,500 mL per day","5,000 mL per day","10,000 mL per day"],"correctIndex":0,"explanation":"Oliguria is commonly defined as urine output below about 400–500 mL/day in adults, depending on reference.","explanationNe":"वयस्कमा दैनिक करिब ४००–५०० mL भन्दा कम पिसाब oliguria मानिन्छ।","topic":"Urinalysis and Routine Clinical Pathology"}$json$::jsonb,true),
('bmlt-urinalysis-routine-path-mock-007','BMLT','BMLT NHPC Licensing','mock','free',2406,$json${"question":"Anuria generally means urine output below approximately:","translation":"","options":["100 mL per day","800 mL per day","1,500 mL per day","3,000 mL per day"],"correctIndex":0,"explanation":"Anuria is commonly defined as urine output below about 100 mL/day.","explanationNe":"Anuria भन्नाले दैनिक करिब १०० mL भन्दा कम पिसाब आउनु हो।","topic":"Urinalysis and Routine Clinical Pathology"}$json$::jsonb,true),
('bmlt-urinalysis-routine-path-mock-008','BMLT','BMLT NHPC Licensing','mock','free',2407,$json${"question":"Polyuria in adults is commonly defined as urine volume above:","translation":"","options":["3 litres per day","500 mL per day","1 litre per week","100 mL per day"],"correctIndex":0,"explanation":"Polyuria is generally urine output exceeding about 3 L/day in adults.","explanationNe":"वयस्कमा दैनिक ३ लिटरभन्दा बढी पिसाब polyuria हो।","topic":"Urinalysis and Routine Clinical Pathology"}$json$::jsonb,true),
('bmlt-urinalysis-routine-path-mock-009','BMLT','BMLT NHPC Licensing','mock','free',2408,$json${"question":"The presence of RBC casts most strongly suggests:","translation":"","options":["Glomerular bleeding or renal parenchymal disease","Contamination from skin","Uncomplicated cystitis only","Normal finding"],"correctIndex":0,"explanation":"RBC casts form within renal tubules and strongly suggest renal origin of bleeding.","explanationNe":"RBC cast मिर्गौलाभित्र बनेको हुने भएकाले renal bleeding संकेत गर्छ।","topic":"Urinalysis and Routine Clinical Pathology"}$json$::jsonb,true),
('bmlt-urinalysis-routine-path-mock-010','BMLT','BMLT NHPC Licensing','mock','free',2409,$json${"question":"A positive leukocyte esterase with pyuria supports:","translation":"","options":["Urinary tract inflammation or infection","Liver cirrhosis","Diabetes insipidus","Hemolytic anemia"],"correctIndex":0,"explanation":"Leukocyte esterase reflects WBCs and supports inflammation, often UTI in the right context.","explanationNe":"Leukocyte esterase positive हुँदा पिसाबमा WBC र संक्रमण/सुजन हुन सक्छ।","topic":"Urinalysis and Routine Clinical Pathology"}$json$::jsonb,true),
('bmlt-urinalysis-routine-path-mock-011','BMLT','BMLT NHPC Licensing','mock','free',2410,$json${"question":"The best method to confirm suspected urinary infection is usually:","translation":"","options":["Urine culture","Urine colour assessment","Serum cholesterol","Stool occult blood"],"correctIndex":0,"explanation":"Urine culture identifies organisms and supports antimicrobial susceptibility testing.","explanationNe":"Urine culture ले जीवाणु पहिचान र antibiotic sensitivity जाँच्न मद्दत गर्छ।","topic":"Urinalysis and Routine Clinical Pathology"}$json$::jsonb,true),
