('bmlt-urinalysis-routine-path-mock-014','BMLT','BMLT NHPC Licensing','mock','free',2413,$json${"question":"Hematuria means:","translation":"","options":["Blood or RBCs in urine","Protein in urine","Glucose in urine","Ketones in urine"],"correctIndex":0,"explanation":"Hematuria is the presence of red blood cells in urine.","explanationNe":"Hematuria भनेको पिसाबमा रगत वा RBC हुनु हो।","topic":"Urinalysis and Routine Clinical Pathology"}$json$::jsonb,true),
('bmlt-urinalysis-routine-path-mock-015','BMLT','BMLT NHPC Licensing','mock','free',2414,$json${"question":"A urine sample for bilirubin testing should be protected from:","translation":"","options":["Light exposure","Room temperature for five minutes","A clean container","Labelling"],"correctIndex":0,"explanation":"Bilirubin is light-sensitive and may degrade with exposure.","explanationNe":"Bilirubin प्रकाशमा बिग्रन सक्छ, त्यसैले प्रकाशबाट जोगाउनुपर्छ।","topic":"Urinalysis and Routine Clinical Pathology"}$json$::jsonb,true),
('bmlt-urinalysis-routine-path-mock-016','BMLT','BMLT NHPC Licensing','mock','free',2415,$json${"question":"The urine sediment is commonly concentrated for microscopy by:","translation":"","options":["Centrifugation","Autoclaving","Boiling","Filtration through cotton"],"correctIndex":0,"explanation":"Centrifugation concentrates formed elements into sediment for microscopy.","explanationNe":"Centrifuge गरेर formed element तल जम्मा गरी microscopy गरिन्छ।","topic":"Urinalysis and Routine Clinical Pathology"}$json$::jsonb,true),
('bmlt-urinalysis-routine-path-mock-017','BMLT','BMLT NHPC Licensing','mock','free',2416,$json${"question":"A common cause of false-positive urine blood dipstick is:","translation":"","options":["Oxidizing cleaning agents","Vitamin C","High water intake","Low specific gravity only"],"correctIndex":0,"explanation":"Oxidizing contaminants can produce false-positive reactions on the blood pad.","explanationNe":"Oxidizing cleaning agent ले blood pad false positive बनाउन सक्छ।","topic":"Urinalysis and Routine Clinical Pathology"}$json$::jsonb,true),
('bmlt-urinalysis-routine-path-mock-018','BMLT','BMLT NHPC Licensing','mock','free',2417,$json${"question":"High-dose vitamin C may cause false-negative results in some urine dipstick tests for:","translation":"","options":["Blood and glucose","Specific gravity only","pH only","Colour only"],"correctIndex":0,"explanation":"Ascorbic acid can interfere with some reagent strip reactions, including blood and glucose pads.","explanationNe":"धेरै vitamin C ले केही dipstick test, जस्तै blood र glucose, false negative बनाउन सक्छ।","topic":"Urinalysis and Routine Clinical Pathology"}$json$::jsonb,true),
